# SPDX-License-Identifier: GPL-3.0-or-later
#
# Generate kernel/fs/ehfs/unicode_data.h: the Unicode 15.0 tables eHFS needs to compare names
# (docs/ehfs.md, decisions E1 and E2): canonical combining classes, canonical decompositions,
# canonical compositions (for NFC) and simple case folding. The input files come from
# https://www.unicode.org/Public/15.0.0/ucd/ (UnicodeData.txt, CompositionExclusions.txt,
# CaseFolding.txt), downloaded into third_party/downloads/unicode-15.0.0/ and checked here by
# SHA-256. The generated file carries the Unicode licence (third_party/downloads/unicode-15.0.0/
# license.txt, Unicode License v3, copied in verbatim).
#
# Usage: python3 -I tools/gen_ehfs_unicode.py [--check]

import hashlib
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DATA = os.path.join(ROOT, "third_party", "downloads", "unicode-15.0.0")
OUT = os.path.join(ROOT, "kernel", "fs", "ehfs", "unicode_data.h")

SHA256 = {
    "UnicodeData.txt": "806e9aed65037197f1ec85e12be6e8cd870fc5608b4de0fffd990f689f376a73",
    "CompositionExclusions.txt": "3b019c0a33c3140cbc920c078f4f9af2680ba4f71869c8d4de5190667c70b6a3",
    "CaseFolding.txt": "cdd49e55eae3bbf1f0a3f6580c974a0263cb86a6a08daa10fbf705b4808a56f7",
    "license.txt": "e7a93b009565cfce55919a381437ac4db883e9da2126fa28b91d12732bc53d96",
}

def read(name):
    path = os.path.join(DATA, name)
    with open(path, "rb") as f:
        data = f.read()
    if hashlib.sha256(data).hexdigest() != SHA256[name]:
        sys.exit(f"gen_ehfs_unicode: {path}: SHA-256 differs from the one recorded here")
    return data.decode("utf-8")


def main():
    ccc = {}
    decomp = {}
    for line in read("UnicodeData.txt").splitlines():
        f = line.split(";")
        cp = int(f[0], 16)
        if int(f[3]) != 0:
            ccc[cp] = int(f[3])
        if f[5] and not f[5].startswith("<"):           # canonical decompositions only
            decomp[cp] = [int(x, 16) for x in f[5].split()]
        # Ranges ("<CJK Ideograph, First>") have no decomposition or class: nothing to keep.

    exclusions = set()
    for line in read("CompositionExclusions.txt").splitlines():
        line = line.split("#")[0].strip()
        if line:
            exclusions.add(int(line, 16))

    # Pairs that compose: not excluded, not a singleton, not a decomposition starting with a non-starter.
    compose = []
    for cp, d in decomp.items():
        if len(d) == 2 and cp not in exclusions and ccc.get(d[0], 0) == 0:
            compose.append((d[0], d[1], cp))
    compose.sort()

    fold = []
    for line in read("CaseFolding.txt").splitlines():
        line = line.split("#")[0].strip()
        if not line:
            continue
        code, status, mapping = [x.strip() for x in line.split(";")[:3]]
        if status in ("C", "S"):                        # simple case folding
            fold.append((int(code, 16), int(mapping, 16)))
    fold.sort()

    flat = []
    index = []
    for cp in sorted(decomp):
        index.append((cp, len(flat), len(decomp[cp])))
        flat.extend(decomp[cp])

    ccc_list = sorted(ccc.items())
    out = [
        "/*",
        " * Copyright (C) 2026 YuanChi Hsieh",
        " * SPDX-License-Identifier: GPL-3.0-or-later",
        " *",
        " * Generated by tools/gen_ehfs_unicode.py. Do not edit.",
        " *",
        " * The tables are derived from the Unicode Character Database 15.0.0 (UnicodeData.txt,",
        " * CompositionExclusions.txt, CaseFolding.txt), whose licence (https://www.unicode.org/license.txt)",
        " * follows:",
        " *",
    ] + [(" *   " + line).rstrip() for line in read("license.txt").splitlines()] + [
        " */",
        "",
        "#ifndef KERNEL_FS_EHFS_UNICODE_DATA_H",
        "#define KERNEL_FS_EHFS_UNICODE_DATA_H",
        "",
        "#include <stdint.h>",
        "",
        "#define EHFS_UNICODE_VERSION 0x0F0000u     /* 15.0.0, recorded in the superblock (E2) */",
        "",
        "/* Canonical combining class of the code points whose class is not 0. */",
        "static const struct { uint32_t cp; uint8_t ccc; } ehfs_ccc[%d] = {" % len(ccc_list),
    ]
    for i in range(0, len(ccc_list), 6):
        out.append("    " + " ".join("{0x%05X, %d}," % c for c in ccc_list[i:i + 6]))
    out += ["};", "",
            "/* Canonical decompositions: code point, first index in ehfs_decomp_cps, length. */",
            "static const struct { uint32_t cp; uint16_t at; uint8_t len; } ehfs_decomp[%d] = {" % len(index)]
    for i in range(0, len(index), 5):
        out.append("    " + " ".join("{0x%05X, %d, %d}," % e for e in index[i:i + 5]))
    out += ["};", "", "static const uint32_t ehfs_decomp_cps[%d] = {" % len(flat)]
    for i in range(0, len(flat), 10):
        out.append("    " + " ".join("0x%05X," % c for c in flat[i:i + 10]))
    out += ["};", "", "/* Canonical compositions: first, second -> composed (sorted by first, second). */",
            "static const struct { uint32_t a, b, c; } ehfs_compose[%d] = {" % len(compose)]
    for i in range(0, len(compose), 4):
        out.append("    " + " ".join("{0x%05X, 0x%05X, 0x%05X}," % c for c in compose[i:i + 4]))
    out += ["};", "", "/* Simple case folding (CaseFolding.txt status C and S). */",
            "static const struct { uint32_t from, to; } ehfs_fold[%d] = {" % len(fold)]
    for i in range(0, len(fold), 6):
        out.append("    " + " ".join("{0x%05X, 0x%05X}," % c for c in fold[i:i + 6]))
    out += ["};", "", "#endif", ""]
    text = "\n".join(out)

    if "--check" in sys.argv:
        if not os.path.exists(OUT) or open(OUT).read() != text:
            sys.exit("gen_ehfs_unicode: kernel/fs/ehfs/unicode_data.h is not what the generator writes")
        return
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w") as f:
        f.write(text)
    print(f"gen_ehfs_unicode: {len(ccc_list)} classes, {len(index)} decompositions, {len(compose)} compositions, "
          f"{len(fold)} case foldings")


main()
